<?php $value=static fn(string $key,string $fallback='Not provided'):string=>trim((string)($profile[$key]??''))!==''?(string)$profile[$key]:$fallback;$date=static fn(?string $date):string=>$date?date('j M Y',strtotime($date)):'Not available';?>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><p class="text-primary fw-semibold mb-1">Member profile</p><h1 class="h2 mb-0"><?=e($value('name','Member'))?></h1><p class="text-secondary mb-0"><?=e($value('email'))?></p></div><a class="btn btn-primary" href="<?=e(url('/profile/edit'))?>">Edit Profile</a></div>
<div class="row g-4"><div class="col-lg-8"><div class="card shadow-sm h-100"><div class="card-body p-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h4 mb-0">Professional details</h2><span class="badge text-bg-primary"><?=e($value('membership_type_name','Membership not selected'))?></span></div><dl class="row mb-0"><dt class="col-sm-4">Telephone</dt><dd class="col-sm-8"><?=e($value('telephone'))?></dd><dt class="col-sm-4">Province</dt><dd class="col-sm-8"><?=e($value('province_name'))?></dd><dt class="col-sm-4">Profession</dt><dd class="col-sm-8"><?=e($value('profession_name'))?></dd><dt class="col-sm-4">Organisation / employer</dt><dd class="col-sm-8"><?=e($value('organisation'))?></dd><dt class="col-sm-4">Job title</dt><dd class="col-sm-8"><?=e($value('job_title'))?></dd><dt class="col-sm-4">Professional biography</dt><dd class="col-sm-8 text-break"><?=nl2br(e($value('biography')))?></dd></dl></div></div></div>
<div class="col-lg-4"><div class="card shadow-sm mb-4"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5">Profile completion</h2><strong><?=e($completion['percent'])?>%</strong></div><div class="progress my-3" role="progressbar" aria-label="Profile completion" aria-valuenow="<?=e($completion['percent'])?>" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:<?=e($completion['percent'])?>%"></div></div><?php if($completion['missing']):?><p class="small mb-1">Still needed:</p><ul class="small mb-0"><?php foreach($completion['missing'] as $label):?><li><?=e(ucfirst($label))?></li><?php endforeach;?></ul><?php else:?><p class="text-success mb-0">Your profile is complete.</p><?php endif;?></div></div><div class="card shadow-sm"><div class="card-body"><h2 class="h5">Account</h2><p><span class="badge <?=($profile['account_status']??'')==='active'?'text-bg-success':'text-bg-secondary'?>"><?=e(ucfirst($value('account_status','Unknown')))?></span></p><dl class="mb-0"><dt>Joined</dt><dd><?=e($date($profile['joined_at']??null))?></dd><dt>Last updated</dt><dd class="mb-0"><?=e($date($profile['profile_updated_at']??$profile['account_updated_at']??null))?></dd></dl></div></div></div></div>
